import React from 'react';
import { Bell } from 'lucide-react';

export const NotificationBell = ({ notifications, onMarkRead }) => {
  const [isOpen, setIsOpen] = React.useState(false);

  return (
    <div className="relative">
      <button 
        onClick={() => setIsOpen(!isOpen)}
        className="relative p-2 hover:bg-sky-100 rounded-full transition-colors"
      >
        <Bell className="w-5 h-5 text-slate-600" />
        {notifications.length > 0 && (
          <span className="absolute -top-1 -right-1 bg-rose-500 text-white text-xs w-5 h-5 rounded-full flex items-center justify-center">
            {notifications.length}
          </span>
        )}
      </button>

      {isOpen && (
        <>
          <div className="fixed inset-0 z-40" onClick={() => setIsOpen(false)} />
          <div className="absolute right-0 mt-2 w-80 bg-white rounded-xl shadow-lg border border-sky-100 z-50 overflow-hidden">
            <div className="p-4 border-b border-sky-100 flex justify-between items-center">
              <h3 className="font-semibold text-slate-800">Notifications</h3>
              <button onClick={() => setIsOpen(false)} className="text-slate-400 hover:text-slate-600">✕</button>
            </div>
            <div className="max-h-96 overflow-y-auto">
              {notifications.length === 0 ? (
                <p className="p-4 text-center text-slate-500">No new notifications</p>
              ) : (
                notifications.map(notif => (
                  <div 
                    key={notif.id}
                    className="p-4 border-b border-sky-50 hover:bg-sky-50 cursor-pointer transition-colors"
                    onClick={() => onMarkRead(notif.id)}
                  >
                    <p className="font-medium text-slate-800 text-sm">{notif.title}</p>
                    <p className="text-slate-500 text-xs mt-1">{notif.message}</p>
                    <p className="text-slate-400 text-xs mt-2">{notif.date}</p>
                  </div>
                ))
              )}
            </div>
          </div>
        </>
      )}
    </div>
  );
};
