import React, { useState } from 'react';
import { useApp } from '../context/AppContext';
import { LoadingSpinner } from '../components/LoadingSpinner';
import { Droplet, Mail, Lock, User } from 'lucide-react';

const demoAccounts = [
  { email: 'john@example.com', role: 'buyer', name: 'Buyer Demo' },
  { email: 'seller@aquapure.co.ke', role: 'seller', name: 'Seller Demo' },
  { email: 'admin@nairobihospital.org', role: 'institution', name: 'Institution Demo' },
  { email: 'admin@aqualink.co.ke', role: 'admin', name: 'Admin Demo' }
];

export const LoginPage = () => {
  const { login, loading } = useApp();
  const [email, setEmail] = useState('');
  const [role, setRole] = useState('buyer');
  const [error, setError] = useState('');

  const handleSubmit = async (e) => {
    e.preventDefault();
    setError('');
    const result = await login(email, role);
    if (!result.success) setError(result.error);
  };

  const useDemo = (demo) => {
    setEmail(demo.email);
    setRole(demo.role);
  };

  return (
    <div className="min-h-screen flex items-center justify-center p-4">
      <div className="w-full max-w-md">
        <div className="text-center mb-8">
          <div className="inline-flex items-center justify-center w-20 h-20 bg-gradient-to-br from-sky-500 to-cyan-600 rounded-2xl shadow-lg mb-4">
            <Droplet className="w-10 h-10 text-white" />
          </div>
          <h1 className="text-3xl font-bold text-slate-800">AquaLink Pro</h1>
          <p className="text-slate-500 mt-2">Smart Water Delivery Marketplace</p>
        </div>

        <div className="bg-white rounded-2xl shadow-xl border border-sky-100 p-8">
          <h2 className="text-xl font-semibold text-slate-800 mb-6">Sign In</h2>
          
          <form onSubmit={handleSubmit} className="space-y-4">
            <div>
              <label className="block text-sm font-medium text-slate-700 mb-2">Email Address</label>
              <div className="relative">
                <Mail className="absolute left-3 top-1/2 -translate-y-1/2 w-5 h-5 text-slate-400" />
                <input
                  type="email"
                  value={email}
                  onChange={(e) => setEmail(e.target.value)}
                  className="w-full pl-10 pr-4 py-3 border border-slate-200 rounded-xl focus:outline-none focus:ring-2 focus:ring-sky-500 focus:border-transparent transition-all"
                  placeholder="you@example.com"
                  required
                />
              </div>
            </div>

            <div>
              <label className="block text-sm font-medium text-slate-700 mb-2">Role</label>
              <select
                value={role}
                onChange={(e) => setRole(e.target.value)}
                className="w-full px-4 py-3 border border-slate-200 rounded-xl focus:outline-none focus:ring-2 focus:ring-sky-500 focus:border-transparent transition-all bg-white"
              >
                <option value="buyer">👤 Buyer</option>
                <option value="seller">🏭 Seller</option>
                <option value="institution">🏥 Institution</option>
                <option value="admin">⚙️ Admin</option>
              </select>
            </div>

            {error && (
              <div className="bg-rose-50 text-rose-600 px-4 py-3 rounded-xl text-sm">
                {error}
              </div>
            )}

            <button
              type="submit"
              disabled={loading}
              className="w-full py-3 bg-gradient-to-r from-sky-500 to-cyan-600 text-white rounded-xl font-semibold hover:from-sky-600 hover:to-cyan-700 transition-all duration-200 disabled:opacity-50 disabled:cursor-not-allowed flex items-center justify-center gap-2"
            >
              {loading ? <LoadingSpinner size="sm" /> : 'Sign In'}
            </button>
          </form>

          <div className="mt-6 pt-6 border-t border-slate-100">
            <p className="text-sm text-slate-500 mb-3 font-medium">Quick Login (Demo):</p>
            <div className="grid grid-cols-2 gap-2">
              {demoAccounts.map((demo) => (
                <button
                  key={demo.email}
                  onClick={() => useDemo(demo)}
                  className={`px-3 py-2 text-xs rounded-lg border transition-all ${
                    email === demo.email 
                      ? 'bg-sky-100 border-sky-300 text-sky-700' 
                      : 'bg-slate-50 border-slate-200 text-slate-600 hover:bg-slate-100'
                  }`}
                >
                  {demo.name}
                </button>
              ))}
            </div>
          </div>
        </div>

        <p className="text-center text-slate-400 text-sm mt-6">
          © 2024 AquaLink. Secure escrow payments powered by blockchain.
        </p>
      </div>
    </div>
  );
};
