import React, { useState } from 'react';
import { Sparkles, X } from 'lucide-react';

export const AIAssistant = ({ getRecommendation }) => {
  const [isOpen, setIsOpen] = useState(false);
  const [tip, setTip] = useState(null);

  const handleOpen = () => {
    if (!tip) {
      setTip(getRecommendation());
    }
    setIsOpen(true);
  };

  const refreshTip = () => {
    setTip(getRecommendation());
  };

  return (
    <>
      <button
        onClick={handleOpen}
        className="fixed bottom-6 right-6 bg-gradient-to-r from-violet-600 to-indigo-600 text-white p-4 rounded-full shadow-lg hover:shadow-xl transition-all duration-300 hover:scale-110 z-40"
      >
        <Sparkles className="w-6 h-6" />
      </button>

      {isOpen && (
        <>
          <div className="fixed inset-0 bg-black/20 backdrop-blur-sm z-40" onClick={() => setIsOpen(false)} />
          <div className="fixed bottom-24 right-6 w-80 bg-white rounded-2xl shadow-2xl border border-violet-100 z-50 overflow-hidden animate-bounce-in">
            <div className="bg-gradient-to-r from-violet-600 to-indigo-600 p-4 flex justify-between items-center">
              <div className="flex items-center gap-2">
                <Sparkles className="w-5 h-5 text-white" />
                <h3 className="font-semibold text-white">AquaAI Assistant</h3>
              </div>
              <button onClick={() => setIsOpen(false)} className="text-white/80 hover:text-white">
                <X className="w-5 h-5" />
              </button>
            </div>
            <div className="p-4">
              <div className="bg-violet-50 rounded-xl p-4 border border-violet-100">
                <p className="text-slate-700 leading-relaxed">{tip || getRecommendation()}</p>
              </div>
              <button 
                onClick={refreshTip}
                className="mt-3 w-full py-2 bg-violet-100 text-violet-700 rounded-lg font-medium hover:bg-violet-200 transition-colors text-sm"
              >
                🔄 Get Another Tip
              </button>
            </div>
          </div>
        </>
      )}
    </>
  );
};
