import React, { useState } from 'react';
import { useApp } from '../context/AppContext';
import { mockProducts, mockOrders, mockTransactions } from '../data/mockData';
import { Card, StatCard } from '../components/Card';
import { StatusBadge } from '../components/StatusBadge';
import { LoadingSpinner } from '../components/LoadingSpinner';
import { SmartInsightsPanel, LiveOrderTracker, SmartAnalyticsWidget } from '../components/SmartComponents';
import { VoiceOrderButton, CarbonFootprintWidget, RecyclingTracker, EcoScoreDashboard, SmartChatAssistant } from '../components/AdvancedComponents';
import { ShoppingCart, Package, Wallet, TrendingUp, Plus, Search, Zap, Clock, MapPin, Leaf, Users, BarChart3 } from 'lucide-react';

export const BuyerDashboard = () => {
  const { user, loading } = useApp();
  const [searchTerm, setSearchTerm] = useState('');
  const [cart, setCart] = useState([]);
  const [activeTab, setActiveTab] = useState('marketplace');

  const filteredProducts = mockProducts.filter(p => 
    p.name.toLowerCase().includes(searchTerm.toLowerCase())
  );

  const myOrders = mockOrders.filter(o => o.buyerId === user?.id);
  const myTransactions = mockTransactions.filter(t => !t.orderId || myOrders.some(o => o.id === t.orderId));

  const addToCart = (product) => {
    setCart(prev => {
      const existing = prev.find(item => item.id === product.id);
      if (existing) {
        return prev.map(item => item.id === product.id ? {...item, qty: item.qty + 1} : item);
      }
      return [...prev, {...product, qty: 1}];
    });
  };

  const cartTotal = cart.reduce((sum, item) => sum + (item.price * item.qty), 0);

  if (loading) return <LoadingSpinner fullScreen />;

  return (
    <div className="p-6 max-w-7xl mx-auto">
      <div className="mb-8">
        <h1 className="text-2xl font-bold text-slate-800">Welcome back, {user?.name}! 👋</h1>
        <p className="text-slate-500 mt-1">Manage your water orders and track deliveries</p>
      </div>

      {/* Stats */}
      <div className="grid grid-cols-1 md:grid-cols-4 gap-6 mb-8">
        <StatCard icon={<Wallet />} title="Wallet Balance" value={`KES ${user?.wallet?.toLocaleString()}`} color="emerald" />
        <StatCard icon={<Package />} title="Total Orders" value={myOrders.length} color="sky" />
        <StatCard icon={<ShoppingCart />} title="Active Orders" value={myOrders.filter(o => o.status !== 'delivered' && o.status !== 'cancelled').length} color="violet" />
        <StatCard icon={<TrendingUp />} title="This Month" value={`KES ${myTransactions.filter(t => t.type === 'debit').reduce((s, t) => s + t.amount, 0).toLocaleString()}`} color="amber" />
      </div>

      {/* Smart Features Grid */}
      <div className="grid grid-cols-1 lg:grid-cols-2 gap-6 mb-8">
        <SmartInsightsPanel userId={user?.id} role="buyer" data={{ purchaseHistory: myOrders }} />
        <SmartAnalyticsWidget userId={user?.id} role="buyer" />
      </div>

      {/* Advanced Smart Features */}
      <div className="grid grid-cols-1 lg:grid-cols-3 gap-6 mb-8">
        <VoiceOrderButton onOrderComplete={(order) => console.log('Voice order:', order)} />
        <CarbonFootprintWidget orderDetails={{ quantity: 10, distance: 15 }} />
        <RecyclingTracker userId={user?.id} />
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-2 gap-6 mb-8">
        <EcoScoreDashboard userId={user?.id} />
        <SmartChatAssistant userContext={{ role: 'buyer', name: user?.name }} />
      </div>

      {/* Active Order Tracking */}
      {myOrders.filter(o => o.status === 'in-transit').length > 0 && (
        <div className="mb-8">
          <h2 className="text-lg font-semibold text-slate-800 mb-4 flex items-center gap-2">
            <Zap className="w-5 h-5 text-sky-600" />
            Live Order Tracking
          </h2>
          <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
            {myOrders.filter(o => o.status === 'in-transit').slice(0, 2).map(order => (
              <LiveOrderTracker key={order.id} orderId={order.id} />
            ))}
          </div>
        </div>
      )}

      {/* Tabs */}
      <div className="flex gap-2 mb-6 border-b border-slate-200">
        {['marketplace', 'orders', 'wallet'].map(tab => (
          <button
            key={tab}
            onClick={() => setActiveTab(tab)}
            className={`px-4 py-3 font-medium capitalize transition-colors relative ${
              activeTab === tab ? 'text-sky-600' : 'text-slate-500 hover:text-slate-700'
            }`}
          >
            {tab}
            {activeTab === tab && <div className="absolute bottom-0 left-0 right-0 h-0.5 bg-sky-600 rounded-full" />}
          </button>
        ))}
      </div>

      {activeTab === 'marketplace' && (
        <div>
          <div className="flex justify-between items-center mb-6">
            <div className="relative flex-1 max-w-md">
              <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-5 h-5 text-slate-400" />
              <input
                type="text"
                placeholder="Search water products..."
                value={searchTerm}
                onChange={(e) => setSearchTerm(e.target.value)}
                className="w-full pl-10 pr-4 py-3 border border-slate-200 rounded-xl focus:outline-none focus:ring-2 focus:ring-sky-500"
              />
            </div>
          </div>

          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6">
            {filteredProducts.map(product => (
              <Card key={product.id} hover className="group">
                <div className="text-4xl mb-4">{product.image}</div>
                <h3 className="font-semibold text-slate-800">{product.name}</h3>
                <p className="text-sm text-slate-500 mt-1">{product.description}</p>
                <div className="flex items-center gap-2 mt-3">
                  <span className="text-xs bg-sky-100 text-sky-700 px-2 py-1 rounded-full">{product.category}</span>
                  <span className="text-xs bg-emerald-100 text-emerald-700 px-2 py-1 rounded-full">{product.purity}% pure</span>
                </div>
                <div className="flex justify-between items-center mt-4">
                  <span className="text-lg font-bold text-slate-800">KES {product.price}</span>
                  <button 
                    onClick={() => addToCart(product)}
                    className="p-2 bg-sky-500 text-white rounded-lg hover:bg-sky-600 transition-colors"
                  >
                    <Plus className="w-5 h-5" />
                  </button>
                </div>
              </Card>
            ))}
          </div>

          {cart.length > 0 && (
            <div className="fixed bottom-0 left-0 right-0 bg-white border-t border-slate-200 p-4 shadow-lg z-30">
              <div className="max-w-7xl mx-auto flex justify-between items-center">
                <div>
                  <p className="font-semibold text-slate-800">{cart.length} items in cart</p>
                  <p className="text-slate-500">Total: <span className="font-bold text-slate-800">KES {cartTotal.toLocaleString()}</span></p>
                </div>
                <button className="px-6 py-3 bg-gradient-to-r from-sky-500 to-cyan-600 text-white rounded-xl font-semibold hover:from-sky-600 hover:to-cyan-700 transition-all">
                  Proceed to Checkout
                </button>
              </div>
            </div>
          )}
        </div>
      )}

      {activeTab === 'orders' && (
        <div className="space-y-4">
          {myOrders.map(order => (
            <Card key={order.id} className="flex flex-col md:flex-row md:items-center justify-between gap-4">
              <div>
                <div className="flex items-center gap-3">
                  <span className="font-semibold text-slate-800">{order.id}</span>
                  <StatusBadge status={order.status} />
                </div>
                <p className="text-sm text-slate-500 mt-1">
                  {order.quantity} units • {order.date} • {order.paymentMethod}
                </p>
              </div>
              <div className="text-right">
                <p className="text-lg font-bold text-slate-800">KES {order.total.toLocaleString()}</p>
                <p className="text-sm text-slate-500">
                  {order.status === 'delivered' ? `Delivered: ${order.deliveryDate}` : 
                   order.status === 'in-transit' ? `ETA: ${order.estimatedDelivery}` : ''}
                </p>
              </div>
            </Card>
          ))}
        </div>
      )}

      {activeTab === 'wallet' && (
        <div>
          <Card className="mb-6 bg-gradient-to-r from-emerald-500 to-teal-600 text-white">
            <div className="flex justify-between items-center">
              <div>
                <p className="text-emerald-100">Available Balance</p>
                <p className="text-3xl font-bold mt-1">KES {user?.wallet?.toLocaleString()}</p>
              </div>
              <button className="px-4 py-2 bg-white/20 backdrop-blur rounded-lg hover:bg-white/30 transition-colors">
                + Top Up
              </button>
            </div>
          </Card>

          <h3 className="font-semibold text-slate-800 mb-4">Transaction History</h3>
          <div className="space-y-3">
            {myTransactions.map(txn => (
              <Card key={txn.id} className="flex justify-between items-center">
                <div className="flex items-center gap-3">
                  <div className={`w-10 h-10 rounded-full flex items-center justify-center ${
                    txn.type === 'credit' ? 'bg-emerald-100 text-emerald-600' : 'bg-rose-100 text-rose-600'
                  }`}>
                    {txn.type === 'credit' ? '↓' : '↑'}
                  </div>
                  <div>
                    <p className="font-medium text-slate-800">{txn.description || txn.method}</p>
                    <p className="text-sm text-slate-500">{txn.date} • {txn.status}</p>
                  </div>
                </div>
                <p className={`font-semibold ${txn.type === 'credit' ? 'text-emerald-600' : 'text-slate-800'}`}>
                  {txn.type === 'credit' ? '+' : '-'} KES {txn.amount.toLocaleString()}
                </p>
              </Card>
            ))}
          </div>
        </div>
      )}
    </div>
  );
};
