import React, { useState } from 'react';
import { useApp } from '../context/AppContext';
import { mockOrders, mockTransactions, mockProducts } from '../data/mockData';
import { Card, StatCard } from '../components/Card';
import { StatusBadge } from '../components/StatusBadge';
import { LoadingSpinner } from '../components/LoadingSpinner';
import { SmartInsightsPanel, SmartAnalyticsWidget, LiveOrderTracker } from '../components/SmartComponents';
import { Building2, Droplets, Calendar, DollarSign, TrendingDown, Clock, Zap } from 'lucide-react';

export const InstitutionDashboard = () => {
  const { user, loading } = useApp();
  const [activeTab, setActiveTab] = useState('overview');

  const myOrders = mockOrders.filter(o => o.buyerId === user?.id);
  const monthlyUsage = user?.monthlyUsage || 500;
  const avgOrderSize = Math.round(myOrders.reduce((s, o) => s + o.quantity, 0) / myOrders.length) || 10;

  if (loading) return <LoadingSpinner fullScreen />;

  return (
    <div className="p-6 max-w-7xl mx-auto">
      <div className="mb-8">
        <h1 className="text-2xl font-bold text-slate-800">Institution Portal 🏥</h1>
        <p className="text-slate-500 mt-1">Manage bulk water orders for your facility</p>
      </div>

      {/* Stats */}
      <div className="grid grid-cols-1 md:grid-cols-4 gap-6 mb-8">
        <StatCard icon={<Building2 />} title="Facility" value={user?.name} color="sky" />
        <StatCard icon={<Droplets />} title="Monthly Usage" value={`${monthlyUsage} units`} color="violet" />
        <StatCard icon={<Calendar />} title="Avg Order Size" value={`${avgOrderSize} units`} color="emerald" />
        <StatCard icon={<DollarSign />} title="Budget Used" value={`KES ${myOrders.reduce((s, o) => s + o.total, 0).toLocaleString()}`} color="amber" />
      </div>

      {/* Smart Features for Institution */}
      <div className="grid grid-cols-1 lg:grid-cols-2 gap-6 mb-8">
        <SmartInsightsPanel userId={user?.id} role="institution" data={{ usageHistory: myOrders }} />
        <SmartAnalyticsWidget userId={user?.id} role="institution" />
      </div>

      {/* Live Tracking for Active Orders */}
      {myOrders.filter(o => o.status === 'in-transit').length > 0 && (
        <div className="mb-8">
          <h2 className="text-lg font-semibold text-slate-800 mb-4 flex items-center gap-2">
            <Zap className="w-5 h-5 text-sky-600" />
            Live Delivery Tracking
          </h2>
          <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
            {myOrders.filter(o => o.status === 'in-transit').slice(0, 2).map(order => (
              <LiveOrderTracker key={order.id} orderId={order.id} />
            ))}
          </div>
        </div>
      )}

      {/* Tabs */}
      <div className="flex gap-2 mb-6 border-b border-slate-200">
        {['overview', 'orders', 'suppliers', 'reports'].map(tab => (
          <button
            key={tab}
            onClick={() => setActiveTab(tab)}
            className={`px-4 py-3 font-medium capitalize transition-colors relative ${
              activeTab === tab ? 'text-sky-600' : 'text-slate-500 hover:text-slate-700'
            }`}
          >
            {tab}
            {activeTab === tab && <div className="absolute bottom-0 left-0 right-0 h-0.5 bg-sky-600 rounded-full" />}
          </button>
        ))}
      </div>

      {activeTab === 'overview' && (
        <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
          <Card>
            <h3 className="font-semibold text-slate-800 mb-4">Quick Actions</h3>
            <div className="grid grid-cols-2 gap-4">
              <button className="p-4 bg-gradient-to-br from-sky-500 to-cyan-600 text-white rounded-xl hover:from-sky-600 hover:to-cyan-700 transition-all text-left">
                <Droplets className="w-6 h-6 mb-2" />
                <p className="font-semibold">Place Order</p>
                <p className="text-xs text-white/80">Quick reorder</p>
              </button>
              <button className="p-4 bg-gradient-to-br from-violet-500 to-purple-600 text-white rounded-xl hover:from-violet-600 hover:to-purple-700 transition-all text-left">
                <Calendar className="w-6 h-6 mb-2" />
                <p className="font-semibold">Schedule</p>
                <p className="text-xs text-white/80">Recurring delivery</p>
              </button>
              <button className="p-4 bg-gradient-to-br from-emerald-500 to-teal-600 text-white rounded-xl hover:from-emerald-600 hover:to-teal-700 transition-all text-left">
                <TrendingDown className="w-6 h-6 mb-2" />
                <p className="font-semibold">Analytics</p>
                <p className="text-xs text-white/80">Usage reports</p>
              </button>
              <button className="p-4 bg-gradient-to-br from-amber-500 to-orange-600 text-white rounded-xl hover:from-amber-600 hover:to-orange-700 transition-all text-left">
                <Clock className="w-6 h-6 mb-2" />
                <p className="font-semibold">Track</p>
                <p className="text-xs text-white/80">Live deliveries</p>
              </button>
            </div>
          </Card>

          <Card>
            <h3 className="font-semibold text-slate-800 mb-4">Consumption Insights</h3>
            <div className="space-y-4">
              <div className="flex justify-between items-center p-3 bg-sky-50 rounded-lg">
                <span className="text-sm text-slate-600">Daily Average</span>
                <span className="font-semibold text-slate-800">{Math.round(monthlyUsage / 30)} units</span>
              </div>
              <div className="flex justify-between items-center p-3 bg-violet-50 rounded-lg">
                <span className="text-sm text-slate-600">Weekly Average</span>
                <span className="font-semibold text-slate-800">{Math.round(monthlyUsage / 4)} units</span>
              </div>
              <div className="flex justify-between items-center p-3 bg-emerald-50 rounded-lg">
                <span className="text-sm text-slate-600">Projected Monthly</span>
                <span className="font-semibold text-slate-800">{monthlyUsage} units</span>
              </div>
              <div className="flex justify-between items-center p-3 bg-amber-50 rounded-lg">
                <span className="text-sm text-slate-600">Cost per Unit</span>
                <span className="font-semibold text-slate-800">KES {Math.round(150 * 0.85)}</span>
              </div>
            </div>
            <p className="text-xs text-slate-500 mt-4">💡 Institutions save 15% with bulk pricing</p>
          </Card>

          <Card className="lg:col-span-2">
            <h3 className="font-semibold text-slate-800 mb-4">Recent Orders</h3>
            <div className="overflow-x-auto">
              <table className="w-full">
                <thead>
                  <tr className="border-b border-slate-200">
                    <th className="text-left py-3 px-4 text-sm font-semibold text-slate-600">Order ID</th>
                    <th className="text-left py-3 px-4 text-sm font-semibold text-slate-600">Product</th>
                    <th className="text-left py-3 px-4 text-sm font-semibold text-slate-600">Quantity</th>
                    <th className="text-left py-3 px-4 text-sm font-semibold text-slate-600">Total</th>
                    <th className="text-left py-3 px-4 text-sm font-semibold text-slate-600">Status</th>
                    <th className="text-left py-3 px-4 text-sm font-semibold text-slate-600">Date</th>
                  </tr>
                </thead>
                <tbody>
                  {myOrders.map(order => {
                    const product = mockProducts.find(p => p.id === order.productId);
                    return (
                      <tr key={order.id} className="border-b border-slate-100 hover:bg-slate-50">
                        <td className="py-3 px-4 text-sm font-medium text-slate-800">{order.id}</td>
                        <td className="py-3 px-4 text-sm text-slate-600">{product?.name || 'Water'}</td>
                        <td className="py-3 px-4 text-sm text-slate-600">{order.quantity} units</td>
                        <td className="py-3 px-4 text-sm font-semibold text-slate-800">KES {order.total.toLocaleString()}</td>
                        <td className="py-3 px-4"><StatusBadge status={order.status} /></td>
                        <td className="py-3 px-4 text-sm text-slate-500">{order.date}</td>
                      </tr>
                    );
                  })}
                </tbody>
              </table>
            </div>
          </Card>
        </div>
      )}

      {activeTab === 'orders' && (
        <div>
          <div className="flex justify-between items-center mb-6">
            <h3 className="font-semibold text-slate-800">Order History</h3>
            <button className="px-4 py-2 bg-sky-500 text-white rounded-lg hover:bg-sky-600 transition-colors">
              + New Bulk Order
            </button>
          </div>
          <div className="space-y-4">
            {myOrders.map(order => (
              <Card key={order.id} className="flex flex-col md:flex-row md:items-center justify-between gap-4">
                <div className="flex-1">
                  <div className="flex items-center gap-3 mb-2">
                    <span className="font-semibold text-slate-800">{order.id}</span>
                    <StatusBadge status={order.status} />
                    <span className="text-xs bg-blue-100 text-blue-700 px-2 py-1 rounded-full">Bulk Order</span>
                  </div>
                  <div className="flex gap-4 text-sm text-slate-500">
                    <span>📦 {order.quantity} units</span>
                    <span>💳 {order.paymentMethod}</span>
                    <span>📅 {order.date}</span>
                  </div>
                </div>
                <div className="text-right">
                  <p className="text-xl font-bold text-slate-800">KES {order.total.toLocaleString()}</p>
                  {order.escrowHeld && (
                    <p className="text-xs text-orange-600 font-medium mt-1">🔒 Payment in Escrow</p>
                  )}
                  {order.status === 'delivered' && order.deliveryDate && (
                    <p className="text-xs text-emerald-600 font-medium mt-1">✓ Delivered: {order.deliveryDate}</p>
                  )}
                </div>
              </Card>
            ))}
          </div>
        </div>
      )}

      {activeTab === 'suppliers' && (
        <div>
          <h3 className="font-semibold text-slate-800 mb-6">Verified Suppliers</h3>
          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
            {[
              { name: 'AquaPure Ltd', rating: 4.8, deliveries: 1250, specialty: 'Spring & Alkaline', verified: true },
              { name: 'CleanWater Co', rating: 4.9, deliveries: 2100, specialty: 'Distilled & Medical', verified: true },
              { name: 'Mountain Fresh', rating: 4.7, deliveries: 890, specialty: 'Mineral Water', verified: true }
            ].map((supplier, idx) => (
              <Card key={idx} hover className="text-center">
                <div className="text-4xl mb-3">🏭</div>
                <h4 className="font-semibold text-slate-800">{supplier.name}</h4>
                <div className="flex justify-center items-center gap-1 mt-2">
                  <span className="text-amber-500">★</span>
                  <span className="font-semibold text-slate-800">{supplier.rating}</span>
                  <span className="text-slate-400 text-sm">({supplier.deliveries} deliveries)</span>
                </div>
                <p className="text-sm text-slate-500 mt-2">{supplier.specialty}</p>
                {supplier.verified && (
                  <span className="inline-block mt-3 text-xs bg-emerald-100 text-emerald-700 px-3 py-1 rounded-full">
                    ✓ Verified Supplier
                  </span>
                )}
                <button className="mt-4 w-full py-2 bg-sky-500 text-white rounded-lg hover:bg-sky-600 transition-colors">
                  Contact Supplier
                </button>
              </Card>
            ))}
          </div>
        </div>
      )}

      {activeTab === 'reports' && (
        <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
          <Card>
            <h3 className="font-semibold text-slate-800 mb-4">Monthly Spending Report</h3>
            <div className="space-y-3">
              {[
                { month: 'January', amount: 45000, units: 300 },
                { month: 'February', amount: 52000, units: 347 },
                { month: 'March', amount: 48000, units: 320 },
                { month: 'April', amount: 61000, units: 407 },
                { month: 'May', amount: 55000, units: 367 },
                { month: 'June', amount: 58000, units: 387 }
              ].map(report => (
                <div key={report.month} className="flex justify-between items-center p-3 bg-slate-50 rounded-lg">
                  <div>
                    <p className="font-medium text-slate-800">{report.month}</p>
                    <p className="text-xs text-slate-500">{report.units} units</p>
                  </div>
                  <p className="font-semibold text-slate-800">KES {report.amount.toLocaleString()}</p>
                </div>
              ))}
            </div>
          </Card>

          <Card>
            <h3 className="font-semibold text-slate-800 mb-4">Sustainability Impact</h3>
            <div className="space-y-6">
              <div className="text-center p-4 bg-emerald-50 rounded-xl">
                <p className="text-3xl font-bold text-emerald-600">2,450</p>
                <p className="text-sm text-emerald-700">Plastic Bottles Saved</p>
              </div>
              <div className="grid grid-cols-2 gap-4">
                <div className="text-center p-4 bg-sky-50 rounded-xl">
                  <p className="text-2xl font-bold text-sky-600">12.5kg</p>
                  <p className="text-xs text-sky-700">CO₂ Reduced</p>
                </div>
                <div className="text-center p-4 bg-violet-50 rounded-xl">
                  <p className="text-2xl font-bold text-violet-600">98%</p>
                  <p className="text-xs text-violet-700">Recycling Rate</p>
                </div>
              </div>
              <div className="p-4 bg-amber-50 rounded-xl border border-amber-200">
                <p className="text-sm text-amber-800">
                  🌱 Your institution is contributing to environmental sustainability by using reusable 20L containers instead of single-use bottles.
                </p>
              </div>
            </div>
          </Card>
        </div>
      )}
    </div>
  );
};
