import React from 'react';
import { AppProvider, useApp } from './context/AppContext';
import { LoginPage } from './pages/LoginPage';
import { BuyerDashboard } from './pages/BuyerDashboard';
import { SellerDashboard } from './pages/SellerDashboard';
import { InstitutionDashboard } from './pages/InstitutionDashboard';
import { AdminDashboard } from './pages/AdminDashboard';
import { NotificationBell } from './components/NotificationBell';
import { AIAssistant } from './components/AIAssistant';
import { Droplet, LogOut, User } from 'lucide-react';

const Dashboard = () => {
  const { user, logout, notifications, markNotificationRead, getAIRecommendation, backendConnected } = useApp();

  const getDashboardForRole = () => {
    switch (user?.role) {
      case 'buyer': return <BuyerDashboard />;
      case 'seller': return <SellerDashboard />;
      case 'institution': return <InstitutionDashboard />;
      case 'admin': return <AdminDashboard />;
      default: return <BuyerDashboard />;
    }
  };

  return (
    <div className="min-h-screen">
      {/* Header */}
      <header className="bg-white border-b border-slate-200 sticky top-0 z-30">
        <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
          <div className="flex justify-between items-center h-16">
            <div className="flex items-center gap-3">
              <div className="flex items-center justify-center w-10 h-10 bg-gradient-to-br from-sky-500 to-cyan-600 rounded-xl">
                <Droplet className="w-5 h-5 text-white" />
              </div>
              <div>
                <h1 className="text-xl font-bold text-slate-800">AquaLink Pro</h1>
                <p className="text-xs text-slate-500 capitalize">{user?.role} Portal</p>
              </div>
            </div>

            <div className="flex items-center gap-4">
              {/* Backend Status */}
              <div className={`hidden md:flex items-center gap-2 px-3 py-1.5 rounded-full text-xs font-medium ${
                backendConnected ? 'bg-emerald-100 text-emerald-700' : 'bg-amber-100 text-amber-700'
              }`}>
                <div className={`w-2 h-2 rounded-full ${backendConnected ? 'bg-emerald-500' : 'bg-amber-500'}`} />
                {backendConnected ? 'Backend Connected' : 'Demo Mode'}
              </div>

              {/* Notifications */}
              <NotificationBell notifications={notifications} onMarkRead={markNotificationRead} />

              {/* User Menu */}
              <div className="flex items-center gap-3 pl-4 border-l border-slate-200">
                <div className="flex items-center gap-2">
                  <div className="w-8 h-8 bg-gradient-to-br from-sky-400 to-cyan-500 rounded-full flex items-center justify-center text-white">
                    <User className="w-4 h-4" />
                  </div>
                  <div className="hidden md:block">
                    <p className="text-sm font-medium text-slate-800">{user?.name}</p>
                    <p className="text-xs text-slate-500">KES {user?.wallet?.toLocaleString()}</p>
                  </div>
                </div>
                <button 
                  onClick={logout}
                  className="p-2 hover:bg-slate-100 rounded-lg transition-colors"
                  title="Logout"
                >
                  <LogOut className="w-5 h-5 text-slate-600" />
                </button>
              </div>
            </div>
          </div>
        </div>
      </header>

      {/* Main Content */}
      <main className="pb-20">
        {getDashboardForRole()}
      </main>

      {/* AI Assistant */}
      <AIAssistant getRecommendation={getAIRecommendation} />
    </div>
  );
};

function App() {
  return (
    <AppProvider>
      <AppContent />
    </AppProvider>
  );
}

function AppContent() {
  const { isAuthenticated } = useApp();
  return isAuthenticated ? <Dashboard /> : <LoginPage />;
}

export default App;
