// Advanced Smart Features for AquaLink - Next-Gen Capabilities

import axios from 'axios';
import { io } from 'socket.io-client';

const API_BASE = 'http://localhost:4000/api';
let socket = null;

// Initialize real-time socket connection
export const initializeSocket = (userId) => {
  if (!socket) {
    socket = io(API_BASE.replace('/api', ''), {
      query: { userId },
      transports: ['websocket']
    });
    
    socket.on('connect', () => {
      console.log('✅ Real-time connection established');
    });
    
    socket.on('order-update', (data) => {
      console.log('📦 Order update:', data);
      // Trigger toast notification
      if (window.showToast) {
        window.showToast(`Order ${data.orderId}: ${data.status}`, 'info');
      }
    });
    
    socket.on('price-alert', (data) => {
      console.log('💰 Price alert:', data);
      if (window.showToast) {
        window.showToast(`Price drop on ${data.productName}!`, 'success');
      }
    });
  }
  return socket;
};

