import React from 'react';

export const Card = ({ children, className = '', hover = false, onClick }) => {
  return (
    <div 
      className={`bg-white rounded-xl shadow-sm border border-sky-100 p-6 ${hover ? 'hover:shadow-lg hover:border-sky-300 transition-all duration-200 cursor-pointer' : ''} ${className}`}
      onClick={onClick}
    >
      {children}
    </div>
  );
};

export const StatCard = ({ icon, title, value, change, color = 'sky' }) => {
  const colorClasses = {
    sky: 'bg-sky-500',
    emerald: 'bg-emerald-500',
    amber: 'bg-amber-500',
    rose: 'bg-rose-500',
    violet: 'bg-violet-500'
  };

  return (
    <Card className="relative overflow-hidden">
      <div className="flex items-center justify-between">
        <div>
          <p className="text-slate-500 text-sm font-medium">{title}</p>
          <p className="text-2xl font-bold text-slate-800 mt-1">{value}</p>
          {change && (
            <p className={`text-sm mt-2 ${change >= 0 ? 'text-emerald-600' : 'text-rose-600'}`}>
              {change >= 0 ? '↑' : '↓'} {Math.abs(change)}% from last month
            </p>
          )}
        </div>
        <div className={`${colorClasses[color]} w-12 h-12 rounded-full flex items-center justify-center text-white text-xl`}>
          {icon}
        </div>
      </div>
    </Card>
  );
};
