import React, { useState } from 'react';
import { useApp } from '../context/AppContext';
import { mockUsers, mockOrders, mockAnalytics } from '../data/mockData';
import { Card, StatCard } from '../components/Card';
import { LoadingSpinner } from '../components/LoadingSpinner';
import { SmartAnalyticsWidget } from '../components/SmartComponents';
import { Users, Package, DollarSign, Shield, Activity, TrendingUp, Zap, Brain } from 'lucide-react';
import { LineChart as ReLineChart, Line, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer, BarChart, Bar, Legend } from 'recharts';

export const AdminDashboard = () => {
  const { user, loading } = useApp();
  const [activeTab, setActiveTab] = useState('overview');

  const totalRevenue = mockAnalytics.revenue.reduce((s, m) => s + m.value, 0);
  const totalOrders = mockAnalytics.orders.reduce((s, m) => s + m.orders, 0);
  const totalUsers = mockUsers.length;

  if (loading) return <LoadingSpinner fullScreen />;

  return (
    <div className="p-6 max-w-7xl mx-auto">
      <div className="mb-8">
        <h1 className="text-2xl font-bold text-slate-800">Admin Dashboard ⚙️</h1>
        <p className="text-slate-500 mt-1">Platform oversight, user management, and analytics</p>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-5 gap-6 mb-8">
        <StatCard icon={<Users />} title="Total Users" value={totalUsers} color="sky" />
        <StatCard icon={<Package />} title="Total Orders" value={totalOrders} change={15} color="violet" />
        <StatCard icon={<DollarSign />} title="Platform Revenue" value={`KES ${(totalRevenue * 0.05).toLocaleString()}`} color="emerald" />
        <StatCard icon={<Shield />} title="Verified Users" value={mockUsers.filter(u => u.verified).length} color="amber" />
        <StatCard icon={<Activity />} title="Active Now" value="24" color="rose" />
      </div>

      {/* Admin Smart Insights */}
      <div className="grid grid-cols-1 lg:grid-cols-3 gap-6 mb-8">
        <Card className="lg:col-span-2 p-6 bg-gradient-to-br from-indigo-50 to-purple-50 border-indigo-200">
          <div className="flex items-center gap-3 mb-4">
            <Brain className="w-7 h-7 text-indigo-600" />
            <h3 className="text-lg font-semibold text-slate-800">AI Platform Insights</h3>
          </div>
          <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
            <div className="p-4 bg-white/70 rounded-xl backdrop-blur-sm">
              <div className="flex items-center gap-2 mb-2">
                <TrendingUp className="w-5 h-5 text-emerald-600" />
                <p className="text-sm font-medium text-slate-700">Growth Prediction</p>
              </div>
              <p className="text-2xl font-bold text-slate-800">+32%</p>
              <p className="text-xs text-slate-500 mt-1">Expected growth next quarter</p>
            </div>
            <div className="p-4 bg-white/70 rounded-xl backdrop-blur-sm">
              <div className="flex items-center gap-2 mb-2">
                <Zap className="w-5 h-5 text-amber-600" />
                <p className="text-sm font-medium text-slate-700">System Efficiency</p>
              </div>
              <p className="text-2xl font-bold text-slate-800">99.9%</p>
              <p className="text-xs text-slate-500 mt-1">Uptime this month</p>
            </div>
            <div className="p-4 bg-white/70 rounded-xl backdrop-blur-sm">
              <div className="flex items-center gap-2 mb-2">
                <Users className="w-5 h-5 text-sky-600" />
                <p className="text-sm font-medium text-slate-700">User Satisfaction</p>
              </div>
              <p className="text-2xl font-bold text-slate-800">4.8/5</p>
              <p className="text-xs text-slate-500 mt-1">Average platform rating</p>
            </div>
            <div className="p-4 bg-white/70 rounded-xl backdrop-blur-sm">
              <div className="flex items-center gap-2 mb-2">
                <Shield className="w-5 h-5 text-violet-600" />
                <p className="text-sm font-medium text-slate-700">Fraud Prevention</p>
              </div>
              <p className="text-2xl font-bold text-slate-800">KES 2.4M</p>
              <p className="text-xs text-slate-500 mt-1">Protected via escrow</p>
            </div>
          </div>
        </Card>
        <SmartAnalyticsWidget userId={user?.id} role="admin" />
      </div>

      <div className="flex gap-2 mb-6 border-b border-slate-200 overflow-x-auto">
        {['overview', 'users', 'transactions', 'analytics', 'settings'].map(tab => (
          <button
            key={tab}
            onClick={() => setActiveTab(tab)}
            className={`px-4 py-3 font-medium capitalize transition-colors relative whitespace-nowrap ${
              activeTab === tab ? 'text-sky-600' : 'text-slate-500 hover:text-slate-700'
            }`}
          >
            {tab}
            {activeTab === tab && <div className="absolute bottom-0 left-0 right-0 h-0.5 bg-sky-600 rounded-full" />}
          </button>
        ))}
      </div>

      {activeTab === 'overview' && (
        <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
          <Card>
            <h3 className="font-semibold text-slate-800 mb-4 flex items-center gap-2">
              <TrendingUp className="w-5 h-5 text-sky-600" /> Platform Growth
            </h3>
            <ResponsiveContainer width="100%" height={250}>
              <ReLineChart data={mockAnalytics.revenue}>
                <CartesianGrid strokeDasharray="3 3" stroke="#e2e8f0" />
                <XAxis dataKey="month" stroke="#64748b" fontSize={12} />
                <YAxis stroke="#64748b" fontSize={12} tickFormatter={(v) => `K${v/1000}`} />
                <Tooltip formatter={(v) => [`KES ${v.toLocaleString()}`, 'Revenue']} />
                <Line type="monotone" dataKey="value" stroke="#0ea5e9" strokeWidth={3} dot={{fill: '#0ea5e9', r: 4}} />
              </ReLineChart>
            </ResponsiveContainer>
          </Card>

          <Card>
            <h3 className="font-semibold text-slate-800 mb-4">System Health</h3>
            <div className="space-y-4">
              {[
                { label: 'API Status', status: 'Operational' },
                { label: 'Database', status: 'Operational' },
                { label: 'Payment Gateway', status: 'Operational' },
                { label: 'Escrow Service', status: 'Operational' },
                { label: 'Notification Service', status: 'Minor Issues' }
              ].map(item => (
                <div key={item.label} className="flex justify-between items-center p-3 bg-slate-50 rounded-lg">
                  <span className="text-sm text-slate-600">{item.label}</span>
                  <span className={`text-xs font-semibold px-3 py-1 rounded-full ${
                    item.status === 'Operational' ? 'bg-emerald-100 text-emerald-700' : 'bg-amber-100 text-amber-700'
                  }`}>{item.status}</span>
                </div>
              ))}
            </div>
          </Card>
        </div>
      )}

      {activeTab === 'users' && (
        <div>
          <h3 className="font-semibold text-slate-800 mb-6">All Users ({mockUsers.length})</h3>
          <div className="overflow-x-auto">
            <table className="w-full">
              <thead>
                <tr className="border-b border-slate-200">
                  <th className="text-left py-3 px-4 text-sm font-semibold text-slate-600">User</th>
                  <th className="text-left py-3 px-4 text-sm font-semibold text-slate-600">Role</th>
                  <th className="text-left py-3 px-4 text-sm font-semibold text-slate-600">Email</th>
                  <th className="text-left py-3 px-4 text-sm font-semibold text-slate-600">Wallet</th>
                  <th className="text-left py-3 px-4 text-sm font-semibold text-slate-600">Status</th>
                </tr>
              </thead>
              <tbody>
                {mockUsers.map(u => (
                  <tr key={u.id} className="border-b border-slate-100 hover:bg-slate-50">
                    <td className="py-3 px-4">
                      <div className="flex items-center gap-3">
                        <span className="text-xl">{u.avatar}</span>
                        <span className="font-medium text-slate-800">{u.name}</span>
                      </div>
                    </td>
                    <td className="py-3 px-4">
                      <span className="text-xs bg-sky-100 text-sky-700 px-2 py-1 rounded-full capitalize">{u.role}</span>
                    </td>
                    <td className="py-3 px-4 text-sm text-slate-600">{u.email}</td>
                    <td className="py-3 px-4 text-sm font-medium text-slate-800">KES {u.wallet?.toLocaleString()}</td>
                    <td className="py-3 px-4">
                      {u.verified ? (
                        <span className="text-xs bg-emerald-100 text-emerald-700 px-2 py-1 rounded-full">✓ Verified</span>
                      ) : (
                        <span className="text-xs bg-amber-100 text-amber-700 px-2 py-1 rounded-full">⏳ Pending</span>
                      )}
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        </div>
      )}

      {activeTab === 'transactions' && (
        <Card>
          <h3 className="font-semibold text-slate-800 mb-4">Recent Transactions</h3>
          <div className="space-y-3">
            {[
              { id: 'TXN-001', type: 'debit', amount: 750, method: 'M-Pesa', status: 'completed', date: '2024-01-15' },
              { id: 'TXN-002', type: 'debit', amount: 600, method: 'Card', status: 'held', date: '2024-01-18' },
              { id: 'TXN-003', type: 'debit', amount: 9000, method: 'Bank', status: 'held', date: '2024-01-19' },
              { id: 'TXN-004', type: 'credit', amount: 5000, method: 'M-Pesa', status: 'completed', date: '2024-01-14' }
            ].map(txn => (
              <div key={txn.id} className="flex justify-between items-center p-3 bg-slate-50 rounded-lg">
                <div>
                  <p className="font-medium text-slate-800">{txn.id}</p>
                  <p className="text-xs text-slate-500">{txn.method} • {txn.date}</p>
                </div>
                <div className="text-right">
                  <p className="font-semibold text-slate-800">KES {txn.amount.toLocaleString()}</p>
                  <span className={`text-xs px-2 py-1 rounded-full ${
                    txn.status === 'completed' ? 'bg-emerald-100 text-emerald-700' : 'bg-orange-100 text-orange-700'
                  }`}>{txn.status}</span>
                </div>
              </div>
            ))}
          </div>
        </Card>
      )}

      {activeTab === 'analytics' && (
        <Card>
          <h3 className="font-semibold text-slate-800 mb-4">Platform Analytics</h3>
          <ResponsiveContainer width="100%" height={300}>
            <BarChart data={mockAnalytics.orders}>
              <CartesianGrid strokeDasharray="3 3" stroke="#e2e8f0" />
              <XAxis dataKey="month" stroke="#64748b" fontSize={12} />
              <YAxis stroke="#64748b" fontSize={12} />
              <Tooltip />
              <Legend />
              <Bar dataKey="orders" fill="#0ea5e9" name="Orders" radius={[4, 4, 0, 0]} />
              <Bar dataKey="deliveries" fill="#22c55e" name="Deliveries" radius={[4, 4, 0, 0]} />
            </BarChart>
          </ResponsiveContainer>
        </Card>
      )}

      {activeTab === 'settings' && (
        <Card>
          <h3 className="font-semibold text-slate-800 mb-4">Platform Settings</h3>
          <div className="space-y-4">
            <div className="flex justify-between items-center p-3 bg-slate-50 rounded-lg">
              <span className="text-sm text-slate-700">Platform Commission (%)</span>
              <input type="text" defaultValue="5" className="w-20 px-3 py-1 border border-slate-200 rounded-lg text-sm text-right" />
            </div>
            <div className="flex justify-between items-center p-3 bg-slate-50 rounded-lg">
              <span className="text-sm text-slate-700">Escrow Auto-release (days)</span>
              <input type="text" defaultValue="7" className="w-20 px-3 py-1 border border-slate-200 rounded-lg text-sm text-right" />
            </div>
            <button className="w-full py-2 bg-sky-500 text-white rounded-lg hover:bg-sky-600 transition-colors">
              Save Settings
            </button>
          </div>
        </Card>
      )}
    </div>
  );
};
