import React, { createContext, useContext, useState, useEffect } from 'react';
import { mockUsers, mockProducts, mockOrders, mockTransactions, mockNotifications, aiTips } from '../data/mockData';

const AppContext = createContext();

export const useApp = () => {
  const context = useContext(AppContext);
  if (!context) throw new Error('useApp must be used within AppProvider');
  return context;
};

export const AppProvider = ({ children }) => {
  const [user, setUser] = useState(null);
  const [loading, setLoading] = useState(false);
  const [notifications, setNotifications] = useState([]);
  const [backendConnected, setBackendConnected] = useState(false);

  // Simulate backend connection check
  useEffect(() => {
    const checkBackend = async () => {
      try {
        const response = await fetch('http://localhost:4000/api/health', { 
          method: 'GET',
          signal: AbortSignal.timeout(2000)
        });
        if (response.ok) setBackendConnected(true);
      } catch {
        setBackendConnected(false);
      }
    };
    checkBackend();
  }, []);

  // Load user from localStorage
  useEffect(() => {
    const savedUser = localStorage.getItem('aqualink_user');
    if (savedUser) {
      setUser(JSON.parse(savedUser));
      loadNotifications(JSON.parse(savedUser));
    }
  }, []);

  const loadNotifications = (currentUser) => {
    setNotifications(mockNotifications.filter(n => !n.read));
  };

  const login = async (email, role) => {
    setLoading(true);
    await new Promise(resolve => setTimeout(resolve, 800));
    
    const foundUser = mockUsers.find(u => u.email === email && u.role === role);
    if (foundUser) {
      setUser(foundUser);
      localStorage.setItem('aqualink_user', JSON.stringify(foundUser));
      loadNotifications(foundUser);
      setLoading(false);
      return { success: true, user: foundUser };
    }
    setLoading(false);
    return { success: false, error: 'Invalid credentials' };
  };

  const logout = () => {
    setUser(null);
    localStorage.removeItem('aqualink_user');
    setNotifications([]);
  };

  const markNotificationRead = (id) => {
    setNotifications(prev => prev.filter(n => n.id !== id));
  };

  const getAIRecommendation = () => {
    const randomIndex = Math.floor(Math.random() * aiTips.length);
    return aiTips[randomIndex];
  };

  const value = {
    user,
    loading,
    notifications,
    backendConnected,
    login,
    logout,
    markNotificationRead,
    getAIRecommendation,
    isAuthenticated: !!user
  };

  return <AppContext.Provider value={value}>{children}</AppContext.Provider>;
};
