// AI Voice Order Component
export const VoiceOrderButton = ({ onOrderComplete }) => {
  const [listening, setListening] = useState(false);
  const [processing, setProcessing] = useState(false);
  const [result, setResult] = useState(null);

  const handleVoiceInput = async () => {
    setListening(true);
    
    // Simulate voice recording (in real app, use Web Speech API)
    setTimeout(async () => {
      setListening(false);
      setProcessing(true);
      
      const orderData = await AIFeatures.processVoiceOrder(new Blob());
      setResult(orderData);
      setProcessing(false);
      
      if (onOrderComplete && orderData.success) {
        onOrderComplete(orderData.extractedOrder);
      }
    }, 2000);
  };

  return (
    <div className="relative">
      <button
        onClick={handleVoiceInput}
        disabled={processing}
        className={`flex items-center gap-2 px-4 py-2 rounded-lg font-medium transition-all ${
          listening 
            ? 'bg-rose-500 text-white animate-pulse' 
            : processing
            ? 'bg-slate-300 text-slate-500 cursor-not-allowed'
            : 'bg-gradient-to-r from-violet-500 to-fuchsia-600 text-white hover:shadow-lg'
        }`}
      >
        {listening ? (
          <>
            <Mic className="w-5 h-5" />
            Listening...
          </>
        ) : processing ? (
          <>
            <Brain className="w-5 h-5 animate-spin" />
            Processing...
          </>
        ) : (
          <>
            <Mic className="w-5 h-5" />
            Voice Order
          </>
        )}
      </button>

      {result && (
        <Card className="absolute top-full left-0 mt-2 p-4 w-80 bg-white shadow-xl border border-violet-200 z-50">
          <div className="flex items-center gap-2 mb-2">
            <CheckCircle className="w-5 h-5 text-emerald-600" />
            <p className="font-semibold text-slate-800">Order Detected</p>
          </div>
          <p className="text-sm text-slate-600 italic mb-3">"{result.transcript}"</p>
          <div className="space-y-2 text-sm">
            <div className="flex justify-between">
              <span className="text-slate-500">Product:</span>
              <span className="font-medium">{result.extractedOrder.product}</span>
            </div>
            <div className="flex justify-between">
              <span className="text-slate-500">Quantity:</span>
              <span className="font-medium">{result.extractedOrder.quantity}</span>
            </div>
            <div className="flex justify-between">
              <span className="text-slate-500">Delivery:</span>
              <span className="font-medium">{result.extractedOrder.deliveryDate}</span>
            </div>
          </div>
          <p className="text-xs text-slate-400 mt-2">Confidence: {(result.confidence * 100).toFixed(0)}%</p>
        </Card>
      )}
    </div>
  );
};

// Carbon Footprint Widget
export const CarbonFootprintWidget = ({ orderDetails }) => {
  const [footprint, setFootprint] = useState(null);
  const [loading, setLoading] = useState(false);

  useEffect(() => {
    calculateFootprint();
  }, [orderDetails]);

  const calculateFootprint = async () => {
    setLoading(true);
    const data = await SustainabilityFeatures.calculateCarbonFootprint(orderDetails || {
      quantity: 10,
      distance: 15
    });
    setFootprint(data);
    setLoading(false);
  };

  if (loading) return <div className="animate-pulse h-32 bg-slate-200 rounded-lg" />;
  if (!footprint) return null;

  return (
    <Card className="p-4 bg-gradient-to-br from-emerald-50 to-teal-50 border-emerald-200">
      <div className="flex items-center gap-2 mb-3">
        <Leaf className="w-6 h-6 text-emerald-600" />
        <h3 className="font-semibold text-slate-800">Environmental Impact</h3>
      </div>
      
      <div className="grid grid-cols-2 gap-4 mb-4">
        <div className="text-center p-3 bg-white/70 rounded-lg">
          <p className="text-2xl font-bold text-emerald-600">{footprint.carbonEmissions}</p>
          <p className="text-xs text-slate-500">{footprint.unit} CO₂</p>
        </div>
        <div className="text-center p-3 bg-white/70 rounded-lg">
          <p className="text-2xl font-bold text-sky-600">{footprint.equivalentTrees}</p>
          <p className="text-xs text-slate-500">Trees to offset</p>
        </div>
      </div>

      <div className="flex items-center justify-between mb-3">
        <span className="text-sm font-medium text-slate-700">Your Badge</span>
        <span className="px-3 py-1 bg-emerald-100 text-emerald-700 rounded-full text-sm font-semibold">
          {footprint.badge}
        </span>
      </div>

      <div className="space-y-2">
        <p className="text-xs font-medium text-slate-500 uppercase">Eco Tips</p>
        {footprint.tips.slice(0, 2).map((tip, idx) => (
          <div key={idx} className="flex items-start gap-2">
            <Leaf className="w-3 h-3 text-emerald-600 mt-0.5" />
            <p className="text-xs text-slate-600">{tip}</p>
          </div>
        ))}
      </div>
    </Card>
  );
};

