// Eco Score Dashboard
export const EcoScoreDashboard = ({ userId }) => {
  const [ecoScore, setEcoScore] = useState(null);

  useEffect(() => {
    loadEcoScore();
  }, [userId]);

  const loadEcoScore = async () => {
    const score = await SustainabilityFeatures.getEcoScore(userId);
    setEcoScore(score);
  };

  if (!ecoScore) return <div className="animate-pulse h-48 bg-slate-200 rounded-lg" />;

  const getGradeColor = (grade) => {
    if (grade.startsWith('A')) return 'text-emerald-600';
    if (grade.startsWith('B')) return 'text-sky-600';
    if (grade.startsWith('C')) return 'text-amber-600';
    return 'text-rose-600';
  };

  return (
    <Card className="p-4 bg-gradient-to-br from-teal-50 to-cyan-50 border-teal-200">
      <div className="flex items-center justify-between mb-4">
        <div className="flex items-center gap-2">
          <Leaf className="w-6 h-6 text-teal-600" />
          <h3 className="font-semibold text-slate-800">Eco Score</h3>
        </div>
        <div className={`text-3xl font-bold ${getGradeColor(ecoScore.grade)}`}>
          {ecoScore.grade}
        </div>
      </div>

      <div className="mb-4">
        <div className="flex justify-between items-end mb-2">
          <span className="text-sm text-slate-600">Overall Score</span>
          <span className="text-2xl font-bold text-teal-600">{ecoScore.score}/{ecoScore.maxScore}</span>
        </div>
        <div className="w-full bg-teal-200 rounded-full h-4">
          <div 
            className="bg-gradient-to-r from-teal-500 to-cyan-500 h-4 rounded-full transition-all"
            style={{ width: `${ecoScore.score}%` }}
          />
        </div>
        <p className="text-xs text-slate-500 mt-1 font-medium">
          {ecoScore.comparisons.ranking} ({ecoScore.comparisons.vsAverage})
        </p>
      </div>

      <div className="grid grid-cols-2 gap-2 mb-4">
        {Object.entries(ecoScore.breakdown).slice(0, 4).map(([key, value]) => (
          <div key={key} className="p-2 bg-white/70 rounded-lg">
            <p className="text-xs text-slate-500 capitalize">{key.replace(/([A-Z])/g, ' $1')}</p>
            <div className="flex items-center gap-2 mt-1">
              <div className="flex-1 bg-slate-200 rounded-full h-2">
                <div 
                  className={`h-2 rounded-full ${value > 80 ? 'bg-emerald-500' : value > 60 ? 'bg-amber-500' : 'bg-rose-500'}`}
                  style={{ width: `${value}%` }}
                />
              </div>
              <span className="text-xs font-bold text-slate-700">{value}%</span>
            </div>
          </div>
        ))}
      </div>

      <div className="space-y-2">
        <p className="text-xs font-medium text-slate-500 uppercase">Achievements</p>
        {ecoScore.achievements.map((achievement, idx) => (
          <div 
            key={idx} 
            className={`flex items-center gap-2 p-2 rounded-lg ${
              achievement.unlocked ? 'bg-white/70' : 'bg-slate-100 opacity-60'
            }`}
          >
            <span className="text-xl">{achievement.icon}</span>
            <div className="flex-1">
              <p className="text-sm font-medium text-slate-700">{achievement.name}</p>
              {!achievement.unlocked && (
                <div className="w-full bg-slate-200 rounded-full h-1.5 mt-1">
                  <div 
                    className="bg-amber-500 h-1.5 rounded-full"
                    style={{ width: `${achievement.progress}%` }}
                  />
                </div>
              )}
            </div>
            {achievement.unlocked ? (
              <CheckCircle className="w-4 h-4 text-emerald-600" />
            ) : (
              <span className="text-xs text-slate-400">{achievement.progress}%</span>
            )}
          </div>
        ))}
      </div>
    </Card>
  );
};

// Real-time Analytics Widget
export const LiveAnalyticsWidget = ({ userId, role }) => {
  const [analytics, setAnalytics] = useState(null);
  const [lastUpdate, setLastUpdate] = useState(new Date());

  useEffect(() => {
    loadAnalytics();
    const interval = setInterval(() => {
      loadAnalytics();
      setLastUpdate(new Date());
    }, 30000); // Update every 30 seconds

    return () => clearInterval(interval);
  }, [userId, role]);

  const loadAnalytics = async () => {
    const data = await AdvancedAnalytics.getLiveDashboard(userId, role);
    setAnalytics(data);
  };

  if (!analytics) return <div className="animate-pulse h-48 bg-slate-200 rounded-lg" />;

  return (
    <Card className="p-4 bg-gradient-to-br from-slate-50 to-gray-50 border-slate-200">
      <div className="flex items-center justify-between mb-4">
        <div className="flex items-center gap-2">
          <BarChart3 className="w-6 h-6 text-slate-600" />
          <h3 className="font-semibold text-slate-800">Live Dashboard</h3>
        </div>
        <div className="flex items-center gap-2 text-xs text-slate-500">
          <Zap className="w-3 h-3 text-emerald-600" />
          Live
          <Clock className="w-3 h-3" />
          {lastUpdate.toLocaleTimeString()}
        </div>
      </div>

      <div className="grid grid-cols-2 gap-3 mb-4">
        <div className="p-3 bg-white rounded-lg shadow-sm">
          <p className="text-xs text-slate-500">Active Users</p>
          <p className="text-xl font-bold text-slate-800">{analytics.realtime.activeUsers}</p>
        </div>
        <div className="p-3 bg-white rounded-lg shadow-sm">
          <p className="text-xs text-slate-500">Orders/Hour</p>
          <p className="text-xl font-bold text-slate-800">{analytics.realtime.ordersInLastHour}</p>
        </div>
        <div className="p-3 bg-white rounded-lg shadow-sm">
          <p className="text-xs text-slate-500">Revenue Today</p>
          <p className="text-lg font-bold text-emerald-600">{analytics.realtime.revenueToday}</p>
        </div>
        <div className="p-3 bg-white rounded-lg shadow-sm">
          <p className="text-xs text-slate-500">Growth</p>
          <p className="text-lg font-bold text-sky-600">{analytics.trends.growth}</p>
        </div>
      </div>

      {/* Mini Chart */}
      <div className="mb-3">
        <p className="text-xs font-medium text-slate-500 mb-2">Hourly Trend</p>
        <div className="flex items-end justify-between h-16 gap-1">
          {analytics.trends.hourly.map((value, idx) => (
            <div 
              key={idx}
              className="flex-1 bg-gradient-to-t from-sky-500 to-cyan-400 rounded-t transition-all hover:from-sky-600 hover:to-cyan-500"
              style={{ height: `${(value / Math.max(...analytics.trends.hourly)) * 100}%` }}
              title={`${value} orders`}
            />
          ))}
        </div>
        <p className="text-xs text-slate-500 text-center mt-1">Peak: {analytics.trends.peak}</p>
      </div>

      {/* Alerts */}
      {analytics.alerts.length > 0 && (
        <div className="space-y-2">
          {analytics.alerts.map((alert, idx) => (
            <div 
              key={idx}
              className={`flex items-center gap-2 p-2 rounded-lg text-sm ${
                alert.type === 'warning' 
                  ? 'bg-amber-50 text-amber-700' 
                  : 'bg-sky-50 text-sky-700'
              }`}
            >
              <AlertCircle className="w-4 h-4" />
              <p>{alert.message}</p>
            </div>
          ))}
        </div>
      )}
    </Card>
  );
};

// Smart Chat Assistant
export const SmartChatAssistant = ({ userContext }) => {
  const [messages, setMessages] = useState([
    { type: 'bot', text: 'Hi! I\'m your AquaLink assistant. How can I help you today?' }
  ]);
  const [input, setInput] = useState('');
  const [typing, setTyping] = useState(false);

  const sendMessage = async () => {
    if (!input.trim()) return;

    const userMessage = input.trim();
    setMessages(prev => [...prev, { type: 'user', text: userMessage }]);
    setInput('');
    setTyping(true);

    const response = await AIFeatures.getChatbotResponse(
      userMessage,
      messages,
      userContext
    );

    setTyping(false);
    setMessages(prev => [...prev, { type: 'bot', text: response.response }]);
  };

  return (
    <Card className="p-4 bg-gradient-to-br from-violet-50 to-purple-50 border-violet-200">
      <div className="flex items-center gap-2 mb-3">
        <MessageSquare className="w-6 h-6 text-violet-600" />
        <h3 className="font-semibold text-slate-800">Smart Assistant</h3>
      </div>

      <div className="h-48 overflow-y-auto mb-3 space-y-2 bg-white/50 rounded-lg p-3">
        {messages.map((msg, idx) => (
          <div 
            key={idx}
            className={`flex ${msg.type === 'user' ? 'justify-end' : 'justify-start'}`}
          >
            <div 
              className={`max-w-[80%] p-2 rounded-lg text-sm ${
                msg.type === 'user'
                  ? 'bg-violet-600 text-white'
                  : 'bg-white text-slate-700 shadow-sm'
              }`}
            >
              {msg.text}
            </div>
          </div>
        ))}
        {typing && (
          <div className="flex justify-start">
            <div className="bg-white p-2 rounded-lg shadow-sm">
              <div className="flex gap-1">
                <div className="w-2 h-2 bg-slate-400 rounded-full animate-bounce" />
                <div className="w-2 h-2 bg-slate-400 rounded-full animate-bounce delay-100" />
                <div className="w-2 h-2 bg-slate-400 rounded-full animate-bounce delay-200" />
              </div>
            </div>
          </div>
        )}
      </div>

      <div className="flex gap-2">
        <input
          type="text"
          value={input}
          onChange={(e) => setInput(e.target.value)}
          onKeyPress={(e) => e.key === 'Enter' && sendMessage()}
          placeholder="Ask me anything..."
          className="flex-1 px-3 py-2 border border-slate-200 rounded-lg text-sm focus:outline-none focus:ring-2 focus:ring-violet-500"
        />
        <button
          onClick={sendMessage}
          className="px-4 py-2 bg-violet-600 text-white rounded-lg hover:bg-violet-700 transition-colors"
        >
          Send
        </button>
      </div>
    </Card>
  );
};

