// Smart Features Service - Advanced AI & Automation for AquaLink

import axios from 'axios';

const API_BASE = 'http://localhost:4000/api';

// Smart Recommendation Engine
export const SmartRecommendations = {
  // AI-powered product recommendations based on purchase history
  forBuyer: async (userId, purchaseHistory) => {
    try {
      const response = await axios.post(`${API_BASE}/ai/recommendations/buyer`, {
        userId,
        purchaseHistory,
        preferences: {
          priceRange: 'medium',
          categories: ['spring', 'alkaline', 'mineral'],
          deliveryFrequency: 'weekly'
        }
      });
      return response.data.recommendations;
    } catch (error) {
      // Fallback to local AI logic
      return generateLocalBuyerRecommendations(purchaseHistory);
    }
  },

  // Inventory optimization suggestions for sellers
  forSeller: async (sellerId, salesData, currentStock) => {
    try {
      const response = await axios.post(`${API_BASE}/ai/recommendations/seller`, {
        sellerId,
        salesData,
        currentStock
      });
      return response.data.recommendations;
    } catch (error) {
      return generateLocalSellerRecommendations(salesData, currentStock);
    }
  },

  // Usage optimization for institutions
  forInstitution: async (institutionId, usageHistory) => {
    try {
      const response = await axios.post(`${API_BASE}/ai/recommendations/institution`, {
        institutionId,
        usageHistory
      });
      return response.data.recommendations;
    } catch (error) {
      return generateLocalInstitutionRecommendations(usageHistory);
    }
  }
};

