import React, { useState, useEffect } from 'react';
import { Lightbulb, TrendingUp, AlertTriangle, CheckCircle, Clock, MapPin, Truck } from 'lucide-react';
import { SmartRecommendations, SmartTracking, SmartAnalytics } from '../services/smartFeatures';
import { Card } from './Card';

// Smart Insights Panel - Shows AI-powered recommendations
export const SmartInsightsPanel = ({ userId, role, data }) => {
  const [insights, setInsights] = useState([]);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    loadInsights();
  }, [userId, role]);

  const loadInsights = async () => {
    setLoading(true);
    try {
      let result;
      if (role === 'buyer') {
        result = await SmartRecommendations.forBuyer(userId, data?.purchaseHistory || []);
      } else if (role === 'seller') {
        result = await SmartRecommendations.forSeller(userId, data?.salesData || [], data?.currentStock || []);
      } else if (role === 'institution') {
        result = await SmartRecommendations.forInstitution(userId, data?.usageHistory || []);
      }
      setInsights(result || []);
    } catch (error) {
      setInsights(['Enable backend for personalized AI recommendations']);
    }
    setLoading(false);
  };

  const getIcon = (insight) => {
    if (insight.includes('save') || insight.includes('discount')) return <TrendingUp className="w-5 h-5 text-emerald-500" />;
    if (insight.includes('alert') || insight.includes('Low stock')) return <AlertTriangle className="w-5 h-5 text-amber-500" />;
    if (insight.includes('Order') || insight.includes('delivery')) return <Clock className="w-5 h-5 text-sky-500" />;
    return <Lightbulb className="w-5 h-5 text-violet-500" />;
  };

  if (loading) {
    return (
      <Card className="p-4">
        <div className="animate-pulse space-y-3">
          <div className="h-5 bg-slate-200 rounded w-1/3"></div>
          <div className="h-4 bg-slate-200 rounded w-full"></div>
          <div className="h-4 bg-slate-200 rounded w-3/4"></div>
        </div>
      </Card>
    );
  }

  return (
    <Card className="p-4 bg-gradient-to-br from-violet-50 to-fuchsia-50 border-violet-200">
      <div className="flex items-center gap-2 mb-4">
        <Lightbulb className="w-6 h-6 text-violet-600" />
        <h3 className="font-semibold text-slate-800">Smart Insights</h3>
      </div>
      <div className="space-y-3">
        {insights.map((insight, idx) => (
          <div key={idx} className="flex items-start gap-3 p-3 bg-white/70 rounded-lg backdrop-blur-sm">
            {getIcon(insight)}
            <p className="text-sm text-slate-700 flex-1">{insight}</p>
          </div>
        ))}
      </div>
    </Card>
  );
};

// Live Order Tracking Component
export const LiveOrderTracker = ({ orderId }) => {
  const [tracking, setTracking] = useState(null);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    loadTracking();
    const interval = setInterval(loadTracking, 30000); // Update every 30s
    return () => clearInterval(interval);
  }, [orderId]);

  const loadTracking = async () => {
    setLoading(true);
    const data = await SmartTracking.trackOrder(orderId);
    setTracking(data);
    setLoading(false);
  };

  if (loading || !tracking) {
    return (
      <Card className="p-4">
        <div className="animate-pulse space-y-3">
          <div className="h-5 bg-slate-200 rounded w-1/2"></div>
          <div className="h-20 bg-slate-200 rounded"></div>
        </div>
      </Card>
    );
  }

  return (
    <Card className="p-4 bg-gradient-to-br from-sky-50 to-cyan-50 border-sky-200">
      <div className="flex items-center justify-between mb-4">
        <div className="flex items-center gap-2">
          <Truck className="w-6 h-6 text-sky-600" />
          <h3 className="font-semibold text-slate-800">Live Tracking</h3>
        </div>
        <span className={`px-3 py-1 rounded-full text-xs font-medium ${
          tracking.status === 'delivered' ? 'bg-emerald-100 text-emerald-700' :
          tracking.status === 'in-transit' ? 'bg-sky-100 text-sky-700' :
          'bg-amber-100 text-amber-700'
        }`}>
          {tracking.status.toUpperCase()}
        </span>
      </div>

      {tracking.status !== 'delivered' && tracking.status !== 'cancelled' && (
        <>
          <div className="mb-4 p-3 bg-white/70 rounded-lg backdrop-blur-sm">
            <div className="flex items-center gap-2 mb-2">
              <MapPin className="w-4 h-4 text-sky-600" />
              <span className="text-sm font-medium text-slate-700">{tracking.location?.address}</span>
            </div>
            <div className="flex items-center gap-2">
              <Clock className="w-4 h-4 text-sky-600" />
              <span className="text-sm text-slate-600">ETA: <span className="font-semibold">{tracking.eta}</span></span>
            </div>
          </div>

          {tracking.driver && (
            <div className="p-3 bg-white/70 rounded-lg backdrop-blur-sm">
              <p className="text-sm font-medium text-slate-700 mb-2">Your Driver</p>
              <div className="flex items-center justify-between">
                <div className="flex items-center gap-2">
                  <div className="w-8 h-8 bg-sky-100 rounded-full flex items-center justify-center text-sky-700 font-semibold">
                    {tracking.driver.name.charAt(0)}
                  </div>
                  <div>
                    <p className="text-sm font-medium text-slate-800">{tracking.driver.name}</p>
                    <p className="text-xs text-slate-500">⭐ {tracking.driver.rating} • {tracking.driver.vehicle}</p>
                  </div>
                </div>
                <a href={`tel:${tracking.driver.phone}`} className="px-3 py-1.5 bg-sky-600 text-white text-sm rounded-lg hover:bg-sky-700 transition-colors">
                  Call
                </a>
              </div>
            </div>
          )}
        </>
      )}

      {/* Timeline */}
      <div className="mt-4 space-y-2">
        <p className="text-xs font-medium text-slate-500 uppercase tracking-wide">Timeline</p>
        {tracking.updates?.map((update, idx) => (
          <div key={idx} className="flex items-start gap-3">
            <div className={`w-2 h-2 rounded-full mt-1.5 ${
              idx === tracking.updates.length - 1 ? 'bg-sky-600' : 'bg-slate-300'
            }`} />
            <div className="flex-1">
              <p className="text-sm text-slate-700">{update.status}</p>
              <p className="text-xs text-slate-500">{update.time} • {update.location}</p>
            </div>
          </div>
        ))}
      </div>
    </Card>
  );
};

// Smart Analytics Dashboard Widget
export const SmartAnalyticsWidget = ({ userId, role }) => {
  const [analytics, setAnalytics] = useState(null);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    loadAnalytics();
  }, [userId, role]);

  const loadAnalytics = async () => {
    setLoading(true);
    const data = await SmartAnalytics.getDashboardInsights(userId, role);
    setAnalytics(data);
    setLoading(false);
  };

  if (loading || !analytics) {
    return (
      <Card className="p-4">
        <div className="animate-pulse space-y-3">
          <div className="h-5 bg-slate-200 rounded w-1/3"></div>
          <div className="grid grid-cols-2 gap-3">
            {[1, 2, 3, 4].map(i => (
              <div key={i} className="h-16 bg-slate-200 rounded"></div>
            ))}
          </div>
        </div>
      </Card>
    );
  }

  const metrics = Object.entries(analytics).filter(([key]) => 
    !key.includes('Trend') && !key.includes('Score')
  ).slice(0, 4);

  return (
    <Card className="p-4 bg-gradient-to-br from-emerald-50 to-teal-50 border-emerald-200">
      <div className="flex items-center gap-2 mb-4">
        <TrendingUp className="w-6 h-6 text-emerald-600" />
        <h3 className="font-semibold text-slate-800">Performance Overview</h3>
      </div>
      
      <div className="grid grid-cols-2 gap-3">
        {metrics.map(([key, value], idx) => (
          <div key={idx} className="p-3 bg-white/70 rounded-lg backdrop-blur-sm">
            <p className="text-xs text-slate-500 capitalize">{key.replace(/([A-Z])/g, ' $1').trim()}</p>
            <p className="text-lg font-bold text-slate-800 mt-1">{value}</p>
          </div>
        ))}
      </div>

      {(analytics.spendingTrend || analytics.revenueGrowth) && (
        <div className="mt-4 p-3 bg-white/70 rounded-lg backdrop-blur-sm">
          <div className="flex items-center gap-2">
            <CheckCircle className="w-4 h-4 text-emerald-600" />
            <p className="text-sm text-slate-700">
              {analytics.spendingTrend ? `Spending trend: ${analytics.spendingTrend}` : 
               analytics.revenueGrowth ? `Revenue growth: ${analytics.revenueGrowth}` : ''}
            </p>
          </div>
        </div>
      )}
    </Card>
  );
};

// Smart Inventory Alert for Sellers
export const SmartInventoryAlert = ({ sellerId, products }) => {
  const [alerts, setAlerts] = useState([]);

  useEffect(() => {
    checkInventory();
  }, [products]);

  const checkInventory = () => {
    const lowStock = products.filter(p => p.stock < 100);
    const outOfStock = products.filter(p => p.stock === 0);
    
    const newAlerts = [];
    if (outOfStock.length > 0) {
      newAlerts.push({
        type: 'critical',
        message: `${outOfStock.length} product(s) out of stock`,
        products: outOfStock
      });
    }
    if (lowStock.length > 0) {
      newAlerts.push({
        type: 'warning',
        message: `${lowStock.length} product(s) running low`,
        products: lowStock
      });
    }
    
    setAlerts(newAlerts);
  };

  if (alerts.length === 0) return null;

  return (
    <div className="space-y-3 mb-6">
      {alerts.map((alert, idx) => (
        <div key={idx} className={`p-4 rounded-xl border-l-4 ${
          alert.type === 'critical' ? 'bg-rose-50 border-rose-500' : 'bg-amber-50 border-amber-500'
        }`}>
          <div className="flex items-center gap-2 mb-2">
            <AlertTriangle className={`w-5 h-5 ${
              alert.type === 'critical' ? 'text-rose-600' : 'text-amber-600'
            }`} />
            <p className={`font-semibold ${
              alert.type === 'critical' ? 'text-rose-700' : 'text-amber-700'
            }`}>{alert.message}</p>
          </div>
          <div className="flex flex-wrap gap-2">
            {alert.products.map(p => (
              <span key={p.id} className="px-2 py-1 bg-white/50 rounded text-xs font-medium text-slate-600">
                {p.name} ({p.stock} left)
              </span>
            ))}
          </div>
        </div>
      ))}
    </div>
  );
};

// Predictive Demand Chart Placeholder
export const DemandForecastChart = ({ forecast }) => {
  if (!forecast?.daily) return null;

  const maxValue = Math.max(...forecast.daily.map(d => d.predicted));

  return (
    <Card className="p-4">
      <h3 className="font-semibold text-slate-800 mb-4">7-Day Demand Forecast</h3>
      <div className="flex items-end justify-between h-40 gap-2">
        {forecast.daily.map((day, idx) => (
          <div key={idx} className="flex-1 flex flex-col items-center gap-2">
            <div 
              className="w-full bg-gradient-to-t from-sky-500 to-cyan-400 rounded-t-lg transition-all duration-500"
              style={{ height: `${(day.predicted / maxValue) * 100}%` }}
              title={`Predicted: ${day.predicted} units`}
            />
            <span className="text-xs text-slate-500">{day.day}</span>
          </div>
        ))}
      </div>
      <div className="mt-4 space-y-2">
        {forecast.insights?.map((insight, idx) => (
          <div key={idx} className="flex items-start gap-2">
            <TrendingUp className="w-4 h-4 text-sky-600 mt-0.5" />
            <p className="text-sm text-slate-600">{insight}</p>
          </div>
        ))}
      </div>
    </Card>
  );
};

export default {
  SmartInsightsPanel,
  LiveOrderTracker,
  SmartAnalyticsWidget,
  SmartInventoryAlert,
  DemandForecastChart
};
